/**
 * Property: a lazy parse and an eager parse of the same input are indistinguishable. Generated by
 * `@cosyte/hl7/arbitraries`: quirky, warning-bearing message text, hostile input (strings and
 * buffers), and messages full of escapes. For each input, in the default mode, with
 * `trimFields: false` and in strict mode, the two parses agree on:
 *
 *   - the error, when there is one: class, code, message, position and snippet;
 *   - every warning, in order, and every `onWarning` call, all made during the parse;
 *   - every field of every segment, read in a generated order on the lazy side: its raw node, its
 *     value, and whether it is marked as altered on the wire;
 *   - `rawSegments`, the version and `toString()`.
 *
 * And `toString()` of a lazy parse nothing has read yet, which writes an unread segment from its own
 * text when that is what its tree would write, is the eager parse's `toString()`.
 */

import fc from "fast-check";
import { checkProperty, propertyTimeout } from "../_helpers/property.js";
import { describe, expect, it } from "vitest";

import { hostileInput, message, messageText } from "../../src/arbitraries/index.js";
import { parseHL7 } from "../../src/index.js";
import type { Hl7Message, Hl7ParseWarning, ParseOptions } from "../../src/index.js";
import { fieldArrivedAltered } from "../../src/parser/wire-fidelity.js";

// The pull-request depth this file ran at before the shared runner, kept; the nightly run's
// COSYTE_PROPERTY_RUNS wins over it (property-depth: kept, not lowered).
const RUN_CONFIG = { numRuns: 200 } as const;

/**
 * Each case parses every input six times and reads every field of every segment four times, which
 * under coverage instrumentation takes longer than the suite's 10 s default. The budget is for
 * this file's own 200 cases and scales with the depth, so the nightly 10,000 is not cut off by it:
 * a timeout prints no seed to replay.
 */
const BUDGET = { timeout: propertyTimeout(60_000, process.env, RUN_CONFIG.numRuns) } as const;

const MODES: readonly ParseOptions[] = [{}, { trimFields: false }, { strict: true }];

type Outcome =
  | { readonly ok: true; readonly msg: Hl7Message; readonly calls: readonly Hl7ParseWarning[] }
  | { readonly ok: false; readonly error: unknown; readonly calls: readonly Hl7ParseWarning[] };

function parse(input: string | Buffer, mode: ParseOptions, lazy: boolean): Outcome {
  const calls: Hl7ParseWarning[] = [];
  try {
    const msg = parseHL7(input, { ...mode, lazy, onWarning: (w) => calls.push(w) });
    return { ok: true, msg, calls: calls.slice() };
  } catch (error) {
    return { ok: false, error, calls };
  }
}

function errorShape(error: unknown): unknown {
  const e = error as { name?: unknown; code?: unknown; position?: unknown; snippet?: unknown };
  return [
    (error as object).constructor,
    e.name,
    e.code,
    (error as Error).message,
    e.position,
    e.snippet,
  ];
}

/** Every field of every segment, as a list of observations, reading segments in `order`. */
function readEveryField(msg: Hl7Message, order: readonly number[]): unknown[] {
  const segments = msg.allSegments();
  const seen: unknown[] = [];
  for (const i of order) {
    const seg = segments[i];
    if (seg === undefined) continue;
    const first = seg.type === "MSH" ? 1 : 0;
    for (let n = first; n <= seg.fields.length + 1; n++) {
      const field = seg.field(n);
      seen.push([i, n, seg.type, field.raw, field.value, fieldArrivedAltered(field.raw)]);
    }
  }
  return seen;
}

/** A permutation of `0 .. n - 1`, from a generated key per index. */
function orderOf(n: number, keys: readonly number[]): number[] {
  return Array.from({ length: n }, (_v, i) => i).sort(
    (a, b) => (keys[a % keys.length] ?? 0) - (keys[b % keys.length] ?? 0) || a - b,
  );
}

function agree(input: string | Buffer, keys: readonly number[]): void {
  for (const mode of MODES) {
    const eager = parse(input, mode, false);
    const lazy = parse(input, mode, true);
    expect(lazy.calls).toEqual(eager.calls);
    if (!eager.ok || !lazy.ok) {
      expect(lazy.ok).toBe(eager.ok);
      if (!eager.ok && !lazy.ok) expect(errorShape(lazy.error)).toEqual(errorShape(eager.error));
      continue;
    }
    expect(lazy.msg.warnings).toEqual(eager.msg.warnings);
    expect(lazy.msg.version).toBe(eager.msg.version);
    const count = eager.msg.allSegments().length;
    const inOrder = Array.from({ length: count }, (_v, i) => i);
    const lazyReads = readEveryField(lazy.msg, orderOf(count, keys));
    const eagerReads = readEveryField(eager.msg, orderOf(count, keys));
    expect(lazyReads).toEqual(eagerReads);
    expect(readEveryField(lazy.msg, inOrder)).toEqual(readEveryField(eager.msg, inOrder));
    expect(lazy.msg.toString()).toBe(eager.msg.toString());
    expect(lazy.msg.rawSegments).toEqual(eager.msg.rawSegments);
    // Nothing a read did reported anything new.
    expect(lazy.msg.warnings).toEqual(eager.msg.warnings);
  }
}

/** `toString()` of a lazy parse, before anything reads a segment, against the eager parse's. */
function writesAsEager(input: string | Buffer): void {
  for (const mode of MODES) {
    const eager = parse(input, mode, false);
    const lazy = parse(input, mode, true);
    if (!eager.ok || !lazy.ok) continue;
    expect(lazy.msg.toString()).toBe(eager.msg.toString());
    // A second write, after the first built what it had to, gives the same text.
    expect(lazy.msg.toString()).toBe(eager.msg.toString());
  }
}

const KEYS = fc.array(fc.integer(), { minLength: 1, maxLength: 16 });

describe("property: a lazy parse and an eager parse agree", () => {
  it("on generated message text, quirks included", BUDGET, () => {
    checkProperty(fc.property(messageText(), KEYS, agree), RUN_CONFIG);
  });

  it("on hostile input, strings and buffers", BUDGET, () => {
    checkProperty(fc.property(hostileInput(), KEYS, agree), RUN_CONFIG);
  });

  it("on messages full of escapes, written out and read back", BUDGET, () => {
    checkProperty(
      fc.property(message({ escapes: true }), KEYS, (msg, keys) => agree(msg.toString(), keys)),
      RUN_CONFIG,
    );
  });

  it("on toString before anything is read, for generated, hostile and escaped text", BUDGET, () => {
    checkProperty(fc.property(messageText(), writesAsEager), RUN_CONFIG);
    checkProperty(fc.property(hostileInput(), writesAsEager), RUN_CONFIG);
    checkProperty(
      fc.property(message({ escapes: true }), (msg) => writesAsEager(msg.toString())),
      RUN_CONFIG,
    );
  });

  it("on edits: the same edits give the same message", BUDGET, () => {
    checkProperty(
      fc.property(messageText(), fc.string({ maxLength: 8 }), (text, value) => {
        const eager = parse(text, {}, false);
        const lazy = parse(text, {}, true);
        if (!eager.ok || !lazy.ok) return;
        for (const msg of [eager.msg, lazy.msg]) {
          msg.setField("MSH.10", value);
          if (msg.part("PID") !== undefined) msg.setField("PID.5.2", value);
          msg.addSegment("NTE", ["1", "", value]);
          msg.removeSegment("NTE");
        }
        expect(lazy.msg.toString()).toBe(eager.msg.toString());
        expect(lazy.msg.rawSegments).toEqual(eager.msg.rawSegments);
      }),
      RUN_CONFIG,
    );
  });
});
